//! Shared conformance vectors and Node differential vectors for the file-server policy core.
//!
//! `tests/vectors/protected-names.json` and `operation-policy.json` are byte copies of the S5 r5 files in
//! `robo-work/tests/views/vectors/` (their SHA-256 values are pinned below and match the s5-candidate-r5 manifest).
//! `unicode-diff.json` is generated by `scripts/gen-unicode-tables.mjs` from Node's ICU (Unicode 17.0).

use rw_fsview::fold::{fold_ignorable_stripped, fold_path_name, nfkc};
use rw_fsview::names::{classify_grant_name, first_protected_component};
use rw_fsview::policy::{Hidden, NodeState, PolicyInput, PolicyOptions, decide_operation};
use rw_proto::json::{self, Value};

fn load(name: &str) -> Value {
    let path = format!("{}/tests/vectors/{name}", env!("CARGO_MANIFEST_DIR"));
    json::parse(&std::fs::read(path).unwrap()).unwrap()
}

fn items<'a>(value: &'a Value, key: &str) -> &'a [Value] {
    match value.get(key) {
        Some(Value::Array(items)) => items,
        other => panic!("{key}: {other:?}"),
    }
}

fn s(value: &Value) -> &str {
    value.as_str().unwrap()
}

#[test]
fn protected_name_vectors() {
    let vectors = load("protected-names.json");
    let mut failures = Vec::new();
    let names = items(&vectors, "names");
    assert_eq!(names.len(), 78);
    for entry in names {
        let got = classify_grant_name(s(entry.get("name").unwrap()), true);
        let ok = if entry.get("protected") == Some(&Value::Bool(true)) {
            got.is_some_and(|verdict| Some(verdict.class.as_str()) == entry.get("class").and_then(Value::as_str)
                && Some(verdict.layer.as_str()) == entry.get("layer").and_then(Value::as_str))
        } else {
            got.is_none()
        };
        if !ok {
            failures.push(s(entry.get("id").unwrap()).to_string());
        }
    }
    let paths = items(&vectors, "paths");
    assert_eq!(paths.len(), 11);
    for entry in paths {
        let segments: Vec<&str> = items(entry, "segments").iter().map(s).collect();
        let got = first_protected_component(&segments, true);
        let ok = match entry.get("firstProtectedIndex").and_then(Value::as_safe_int) {
            None => got.is_none(),
            Some(index) => got.is_some_and(|(at, verdict)| at as i64 == index && Some(verdict.class.as_str()) == entry.get("class").and_then(Value::as_str)),
        };
        if !ok {
            failures.push(s(entry.get("id").unwrap()).to_string());
        }
    }
    assert!(failures.is_empty(), "failing vectors: {failures:?}");
}

#[test]
fn hardening_layer_negative_control() {
    // Without the hardening layer the default-ignorable vectors must fail: the layer has an effect.
    let vectors = load("protected-names.json");
    let ignorable: Vec<&Value> = items(&vectors, "names").iter().filter(|entry| entry.get("layer").and_then(Value::as_str) == Some("default-ignorable")).collect();
    assert!(!ignorable.is_empty());
    for entry in ignorable {
        assert!(classify_grant_name(s(entry.get("name").unwrap()), false).is_none());
    }
}

fn policy_case(entry: &Value, op: &str) -> (String, bool) {
    let names: Vec<(&str, &[u8])> = entry.get("names").and_then(Value::as_object).map(|pairs| {
        pairs.iter().map(|(role, name)| (role.as_str(), name.as_str().unwrap().as_bytes())).collect()
    }).unwrap_or_default();
    let nodes: Vec<(&str, Option<NodeState>)> = entry.get("nodes").and_then(Value::as_object).map(|pairs| {
        pairs.iter().map(|(role, state)| (role.as_str(), state.as_str().and_then(NodeState::parse))).collect()
    }).unwrap_or_default();
    let hidden = match entry.get("hiddenDescendants") {
        None => None,
        Some(Value::Bool(false)) => Some(Hidden::No),
        Some(Value::Bool(true)) => Some(Hidden::Yes),
        Some(_) => Some(Hidden::Unknown),
    };
    let reviewed: Vec<&str> = entry.get("options").and_then(|options| options.get("reviewedXattrs")).map(|list| match list {
        Value::Array(items) => items.iter().map(s).collect(),
        _ => vec![],
    }).unwrap_or_default();
    let input = PolicyInput {
        op,
        names,
        nodes,
        moves_directory: entry.get("movesDirectory").and_then(Value::as_bool),
        hidden_descendants: hidden,
        attribute: entry.get("attribute").and_then(Value::as_str),
    };
    let decision = decide_operation(&input, &PolicyOptions { reviewed_xattrs: &reviewed, ..PolicyOptions::default() });
    let expect = entry.get("expect").unwrap();
    let ok = Some(decision.outcome.as_str()) == expect.get("outcome").and_then(Value::as_str)
        && Some(decision.code) == expect.get("code").and_then(Value::as_str)
        && expect.get("postCheck").is_none_or(|want| decision.post_check.map(|post| post.as_str()) == want.as_str())
        && expect.get("noDataIo").is_none_or(|want| Some(decision.no_data_io) == want.as_bool())
        && (decision.outcome.as_str() != "absent" || decision.errno_hint == Some("ENOENT"));
    (format!("{}:{op}", s(entry.get("id").unwrap())), ok)
}

#[test]
fn operation_policy_vectors() {
    let vectors = load("operation-policy.json");
    let cases = items(&vectors, "cases");
    assert_eq!(cases.len(), 71);
    let mut expanded = 0;
    let mut failures = Vec::new();
    for entry in cases {
        for op in items(entry, "ops") {
            let (id, ok) = policy_case(entry, s(op));
            expanded += 1;
            if !ok {
                failures.push(id);
            }
        }
    }
    assert!(failures.is_empty(), "failing: {failures:?}");
    assert!(expanded > 150, "{expanded}");
}

#[test]
fn shared_vector_files_are_present_and_not_truncated() {
    // Only presence and a minimum size are checked here (review N2). The byte identity with the frozen S5 files is the
    // sha256 check of gate G04 in scripts/gates.sh.
    let sizes = [("protected-names.json", load_len("protected-names.json")), ("operation-policy.json", load_len("operation-policy.json"))];
    for (name, size) in sizes {
        assert!(size > 1000, "{name}");
    }
}

fn load_len(name: &str) -> usize {
    std::fs::read(format!("{}/tests/vectors/{name}", env!("CARGO_MANIFEST_DIR"))).unwrap().len()
}

fn cps(value: &Value) -> String {
    items_of(value).iter().map(|cp| char::from_u32(cp.as_safe_int().unwrap() as u32).unwrap()).collect()
}

fn items_of(value: &Value) -> &[Value] {
    match value {
        Value::Array(items) => items,
        other => panic!("{other:?}"),
    }
}

#[test]
fn nfkc_and_lowercase_match_node_for_every_code_point() {
    let vectors = load("unicode-diff.json");
    assert_eq!(vectors.get("unicode").and_then(Value::as_str), Some("17.0"));
    let mut nfkc_expected = std::collections::HashMap::new();
    for pair in items(&vectors, "nfkcSingles") {
        let pair = items_of(pair);
        nfkc_expected.insert(pair[0].as_safe_int().unwrap() as u32, cps(&pair[1]));
    }
    let mut lower_expected = std::collections::HashMap::new();
    for pair in items(&vectors, "lowerSingles") {
        let pair = items_of(pair);
        lower_expected.insert(pair[0].as_safe_int().unwrap() as u32, cps(&pair[1]));
    }
    let mut checked = 0u32;
    let mut nfkc_failures = Vec::new();
    let mut lower_failures = Vec::new();
    for cp in 0..=0x10FFFFu32 {
        let Some(character) = char::from_u32(cp) else { continue };
        let single = character.to_string();
        let want = nfkc_expected.get(&cp).cloned().unwrap_or_else(|| single.clone());
        if nfkc(&single) != want {
            nfkc_failures.push(cp);
        }
        let want = lower_expected.get(&cp).cloned().unwrap_or_else(|| single.clone());
        if single.to_lowercase() != want {
            lower_failures.push(cp);
        }
        checked += 1;
    }
    assert_eq!(checked, 0x110000 - 0x800);
    assert!(nfkc_failures.is_empty(), "NFKC differs for {} code points, first {:x?}", nfkc_failures.len(), &nfkc_failures[..nfkc_failures.len().min(10)]);
    assert!(lower_failures.is_empty(), "toLowerCase differs for {} code points, first {:x?}", lower_failures.len(), &lower_failures[..lower_failures.len().min(10)]);
}

fn class_code(verdict: Option<rw_fsview::names::Verdict>) -> [u32; 2] {
    match verdict {
        None => [0, 0],
        Some(verdict) => [
            match verdict.class.as_str() { "controller_state" => 1, "agent_data" => 2, "host_state" => 3, "private_session" => 4, _ => 5 },
            if verdict.layer.as_str() == "ploinky-fold" { 1 } else { 2 },
        ],
    }
}

fn verdict_value(value: &Value) -> Option<(String, String)> {
    match value {
        Value::Null => None,
        Value::Array(items) => Some((s(&items[0]).to_string(), s(&items[1]).to_string())),
        other => panic!("{other:?}"),
    }
}

struct Mulberry(u32);
impl Mulberry {
    fn next(&mut self) -> u32 {
        self.0 = self.0.wrapping_add(0x6D2B79F5);
        let mut t = self.0;
        t = (t ^ (t >> 15)).wrapping_mul(t | 1);
        t ^= t.wrapping_add((t ^ (t >> 7)).wrapping_mul(t | 61));
        t ^ (t >> 14)
    }
}

fn fnv(hash: &mut u64, numbers: &[u32]) {
    for number in numbers {
        for shift in [0, 8, 16, 24] {
            *hash ^= ((number >> shift) & 0xFF) as u64;
            *hash = hash.wrapping_mul(0x100000001b3);
        }
    }
}

#[test]
fn fold_matches_node_on_explicit_and_hashed_corpus() {
    let vectors = load("unicode-diff.json");
    // Explicit cases, with readable failures.
    let explicit = items(&vectors, "explicit");
    assert_eq!(explicit.len(), 3000);
    for case in explicit {
        let input = cps(case.get("input").unwrap());
        assert_eq!(fold_path_name(&input), cps(case.get("fold").unwrap()), "fold {:x?}", input.chars().map(|c| c as u32).collect::<Vec<_>>());
        assert_eq!(fold_ignorable_stripped(&input), cps(case.get("stripped").unwrap()), "stripped {input:?}");
        let hard = classify_grant_name(&input, true).map(|v| (v.class.as_str().to_string(), v.layer.as_str().to_string()));
        assert_eq!(hard, verdict_value(case.get("hard").unwrap()), "{input:?}");
        let soft = classify_grant_name(&input, false).map(|v| (v.class.as_str().to_string(), v.layer.as_str().to_string()));
        assert_eq!(soft, verdict_value(case.get("soft").unwrap()), "{input:?}");
    }
    // The hashed corpus, rebuilt from the same pools and seed.
    let corpus = vectors.get("corpus").unwrap();
    let pools: Vec<Vec<Vec<u32>>> = items(corpus, "pools").iter().map(|pool| {
        items_of(pool).iter().map(|token| items_of(token).iter().map(|cp| cp.as_safe_int().unwrap() as u32).collect()).collect()
    }).collect();
    let count = corpus.get("count").and_then(Value::as_safe_int).unwrap();
    let mut rng = Mulberry(corpus.get("seed").and_then(Value::as_safe_int).unwrap() as u32);
    let mut hash: u64 = 0xcbf29ce484222325;
    for _ in 0..count {
        let tokens = 1 + rng.next() % 8;
        let mut input: Vec<u32> = Vec::new();
        for _ in 0..tokens {
            let pool = &pools[(rng.next() as usize) % pools.len()];
            input.extend_from_slice(&pool[(rng.next() as usize) % pool.len()]);
        }
        let text: String = input.iter().map(|cp| char::from_u32(*cp).unwrap()).collect();
        let fold: Vec<u32> = fold_path_name(&text).chars().map(|c| c as u32).collect();
        let stripped: Vec<u32> = fold_ignorable_stripped(&text).chars().map(|c| c as u32).collect();
        let mut record = vec![input.len() as u32];
        record.extend_from_slice(&input);
        record.push(fold.len() as u32);
        record.extend_from_slice(&fold);
        record.push(stripped.len() as u32);
        record.extend_from_slice(&stripped);
        record.extend_from_slice(&class_code(classify_grant_name(&text, true)));
        record.extend_from_slice(&class_code(classify_grant_name(&text, false)));
        fnv(&mut hash, &record);
    }
    assert_eq!(format!("{hash:016x}"), corpus.get("fnv1a64").and_then(Value::as_str).unwrap(), "300 000-string corpus differs from Node");
}

#[test]
fn naive_fold_negative_control() {
    // A fold without NFKC (lowercase and strip only) misses the fullwidth and Kelvin-sign vectors.
    let naive = |name: &str| name.to_lowercase().trim_end_matches(['.', ' ']).to_string();
    assert_ne!(naive("\u{FF0E}data"), ".data");
    assert_eq!(fold_path_name("\u{FF0E}data"), ".data");
}
